const platform=u=>{u=String(u||'').toLowerCase();return u.includes('boamp.fr')?'BOAMP':u.includes('marches-publics.gouv.fr')?'PLACE':u.includes('aws-achat')||u.includes('marches-publics.info')?'AWS-Achat':u.includes('e-marchespublics.com')?'e-marchespublics.com':u.includes('maximilien')?'Maximilien':u.includes('klekoon')?'Klekoon':u.includes('ternum-bfc')||u.includes('e-bourgogne')?'la plateforme Bourgogne-Franche-Comté':u.includes('megalis.bretagne')?'Mégalis Bretagne':u.includes('achatpublic.com')?'achatpublic.com':null};
